#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "usb/usb_host.h"

#define DJI_VID 0x2CA3
#define DJI_PID 0x0020
#define EP_OUT 0x04
#define EP_IN  0x85

// Verified drone-side subset (generated by comm_mkdupc; sender PC(10,0), ACK_AFTER_EXEC, seq 1..6).
// AU channel groups 2.4G/5.8G, OFDM power limits 2.4G/5.8G (FFFF), channel map + flag.
static const uint8_t FRAME_1[] = { 0x55, 0x17, 0x04, 0x38, 0x0a, 0x09, 0x01, 0x00, 0x40, 0x07, 0x30, 0x41, 0x55, 0x00, 0x00, 0x41, 0x55, 0x00, 0x00, 0x01, 0x00, 0xbf, 0x1b };
static const uint8_t FRAME_2[] = { 0x55, 0x17, 0x04, 0x38, 0x0a, 0x09, 0x02, 0x00, 0x40, 0x07, 0x30, 0x41, 0x55, 0x00, 0x00, 0x41, 0x55, 0x00, 0x00, 0x01, 0x00, 0xc1, 0xc3 };
static const uint8_t FRAME_3[] = { 0x55, 0x18, 0x04, 0x20, 0x0a, 0x09, 0x03, 0x00, 0x40, 0x09, 0x27, 0x00, 0x02, 0x48, 0x00, 0xff, 0xff, 0x02, 0x00, 0x00, 0x00, 0x00, 0xef, 0x7a };
static const uint8_t FRAME_4[] = { 0x55, 0x18, 0x04, 0x20, 0x0a, 0x09, 0x04, 0x00, 0x40, 0x09, 0x27, 0x00, 0x02, 0x63, 0x00, 0xff, 0xff, 0x03, 0x00, 0x00, 0x00, 0x00, 0x1c, 0x9d };
static const uint8_t FRAME_5[] = { 0x55, 0x11, 0x04, 0x92, 0x0a, 0x07, 0x05, 0x00, 0x40, 0x07, 0x18, 0xff, 0x41, 0x55, 0x00, 0xca, 0x8e };
static const uint8_t FRAME_6[] = { 0x55, 0x0e, 0x04, 0x66, 0x0a, 0x09, 0x06, 0x00, 0x40, 0x07, 0x19, 0xc0, 0xa3, 0x30 };

static const uint8_t *FRAMES[] = { FRAME_1, FRAME_2, FRAME_3, FRAME_4, FRAME_5, FRAME_6 };
static const uint16_t FRAME_LEN[] = { sizeof(FRAME_1), sizeof(FRAME_2), sizeof(FRAME_3),
                                      sizeof(FRAME_4), sizeof(FRAME_5), sizeof(FRAME_6) };

static void xfer_cb(usb_transfer_t *t)
{
    // completion only; transfers are freed after the (synchronous) submit returns
}

static esp_err_t set_configuration(usb_device_handle_t dev)
{
    usb_transfer_t *t = NULL;
    usb_host_transfer_alloc(sizeof(usb_setup_packet_t), 0, &t);
    usb_setup_packet_t *sp = (usb_setup_packet_t *)t->data_buffer;
    sp->bmRequestType = 0x00;                  // OUT, standard, device
    sp->bRequest = USB_B_REQUEST_SET_CONFIGURATION;
    sp->wValue = 1;
    sp->wIndex = 0;
    sp->wLength = 0;
    t->device_handle = dev;
    t->bEndpointAddress = 0;
    t->num_bytes = sizeof(usb_setup_packet_t);
    t->callback = xfer_cb;
    esp_err_t err = usb_host_transfer_submit(t);
    usb_host_transfer_free(t);
    return err;
}

static int find_channel(usb_device_handle_t dev)
{
    const usb_config_desc_t *cd = NULL;
    if (usb_host_get_active_config_descriptor(dev, &cd) != ESP_OK)
        return -1;
    uint8_t *p = (uint8_t *)cd->val;
    int remaining = cd->wTotalLength - 9;
    int iface = -1, ep_out = 0, ep_in = 0;
    while (remaining > 0) {
        if (p[1] == 0x04) {                              // interface descriptor
            if (p[5] == 0xFF && p[6] == 0x43)            // vendor class, DJI subclass
                iface = p[2];
        } else if (p[1] == 0x05 && iface >= 0) {         // endpoint descriptor
            if (p[2] == EP_OUT) ep_out = p[2];
            if (p[2] == EP_IN)  ep_in = p[2];
        }
        remaining -= p[0];
        p += p[0];
    }
    return (iface >= 0 && ep_out && ep_in) ? iface : -1;
}

void app_main(void)
{
    usb_host_config_t hcfg = { .skip_phy_setup = false, .intr_flags = ESP_INTR_FLAG_LEVEL1 };
    usb_host_install(&hcfg);

    usb_host_client_config_t ccfg = { .is_synchronous = true, .max_num_event_msg = 5 };
    usb_host_client_handle_t client = NULL;
    usb_host_client_register(&ccfg, &client);

    for (;;) {
        usb_device_handle_t dev = NULL;
        for (uint8_t a = 1; a < 8 && dev == NULL; a++)       // wait for the DJI device
            usb_host_device_open(client, a, &dev);

        const usb_device_desc_t *dd = NULL;
        usb_host_get_device_descriptor(dev, &dd);
        ESP_LOGI("fccbox", "device %04x:%04x", dd->idVendor, dd->idProduct);

        int iface = find_channel(dev);
        if (iface < 0) {
            ESP_LOGE("fccbox", "no DJI vendor bulk channel found");
        } else if (set_configuration(dev) == ESP_OK &&
                   usb_host_interface_claim(client, dev, iface, 0) == ESP_OK) {
            for (int i = 0; i < 6; i++) {
                usb_transfer_t *t = NULL;
                usb_host_transfer_alloc(FRAME_LEN[i], 0, &t);
                memcpy(t->data_buffer, FRAMES[i], FRAME_LEN[i]);
                t->device_handle = dev;
                t->bEndpointAddress = EP_OUT;
                t->num_bytes = FRAME_LEN[i];
                t->callback = xfer_cb;
                esp_err_t err = usb_host_transfer_submit(t);
                usb_host_transfer_free(t);
                ESP_LOGI("fccbox", "frame %d/%d: %s", i + 1, 6,
                         err == ESP_OK ? "sent" : esp_err_to_name(err));
                vTaskDelay(pdMS_TO_TICKS(300));
            }
            ESP_LOGI("fccbox", "done - RC screen should show FCC; aircraft power-cycle reverts");
        } else {
            ESP_LOGE("fccbox", "set_configuration/claim failed");
        }
        ESP_LOGI("fccbox", "idle (reset board or re-plug to run again)");
        vTaskDelay(portMAX_DELAY);
    }
}
